  "p.demo.f_financials_d": "ポートフォリオ全体の予算、実支出、差異です。",
  "p.demo.f_cost_risk_t": "コストリスク",
  "p.demo.f_cost_risk_d": "想定コストの分布を、P50 と P80 とともに表示します。",
