  "p.demo.f_costs_t": "プロジェクトのコスト",
  "p.demo.f_costs_d": "単価表に基づく人件費と、タスク別のその他のコストです。",
  "p.demo.f_resources_t": "リソース",
  "p.demo.f_resources_d": "架空の 8 人の担当者、その役割、割り当て先です。",
