  "p.hammock.heading": "ハンモック: 他のタスクにまたがるサマリータスク",
  "p.hammock.says":
    "ハンモックは、この計画のうちリンクしたタスクの最も早い開始から最も遅い終了までを日付とするサマリーです。依存関係のネットワークには含まれないため、どのタスクのフロートや終了日も変わりません。タスクをハンモックにできるのは、所要期間、作業量、制約、依存関係がなく、計画開始日がクリアされている場合だけです。再びタスクに戻すと、そのリンクはすべて削除されます。ハンモックがリンクできるのは、この計画のタスクまたは別のハンモックで、自分自身、重複、ループはできません。",
